set -eu; printf 'PRE_RESTART_BOOT_ID='; cat /proc/sys/kernel/random/boot_id; printf 'APACHE_ACTIVE='; systemctl is-active apache2; printf 'APACHE_ENABLED='; systemctl is-enabled apache2; ss -ltn '( sport = :8080 )'; base="http://$NODE_IP:8080"; curl --noproxy '*' -sS -H 'Host: docs.branch.test' -o /tmp/pre-docs.out -w 'docs_status=%{http_code}
' "$base/"; cmp -s /tmp/pre-docs.out /srv/legacy2/name-based-web-tenants/docs/index.html && printf 'docs_exact_source=yes
'; curl --noproxy '*' -sS -H 'Host: orders.branch.test' -o /tmp/pre-orders.out -w 'orders_status=%{http_code}
' "$base/"; cmp -s /tmp/pre-orders.out /srv/legacy2/name-based-web-tenants/orders/index.html && printf 'orders_exact_source=yes
'; curl --noproxy '*' -sS -H 'Host: unknown.branch.test' -o /tmp/pre-unknown.out -w 'unknown_status=%{http_code}
' "$base/"; find /srv/legacy2/name-based-web-tenants -type f -exec sha256sum {} \; | sort

